import{_ as e,o as t,c,a2 as i}from"./chunks/framework.D0_YsCyK.js";const h=JSON.parse('{"title":"审查域 C 报告：节点/延迟/调优/路由/GitHub 镜像","description":"","frontmatter":{},"headers":[],"relativePath":"audit/C-node.md","filePath":"audit/C-node.md","lastUpdated":1792447441000}'),d={name:"audit/C-node.md"};function r(l,o,a,n,u,s){return t(),c("div",null,[...o[0]||(o[0]=[i('<h1 id="审查域-c-报告-节点-延迟-调优-路由-github-镜像" tabindex="-1">审查域 C 报告：节点/延迟/调优/路由/GitHub 镜像 <a class="header-anchor" href="#审查域-c-报告-节点-延迟-调优-路由-github-镜像" aria-label="Permalink to &quot;审查域 C 报告：节点/延迟/调优/路由/GitHub 镜像&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：<code>go-backend/internal/http/handler/node_latency.go</code>（538行）、<code>node_tune.go</code>（58行）、<code>node_route.go</code>（377行）、<code>gh_mirror.go</code>（419行）、<code>go-gost/x/socket/tuning.go</code>（316行）</li><li>发现问题数：P0 0 个 / P1 0 个 / <strong>P2 1 个</strong> / P3 4 个</li><li>实际执行的测试： <ul><li>编写并运行 8 个 handler 层单元验证（<code>parseLatencyTargets</code> 边界、<code>targetsForNode</code> 回退、<code>renamedTargets</code> 改名跟随、<code>classifyRoute</code> 分类、<code>routeHopNet</code> 前缀、<code>routeFresh</code> 缓存、<code>parseGHMirrorPath</code> SSRF 防护、<code>ghMirrorCheckRedirect</code> 重定向限制）——全部通过</li><li>编写并运行 3 个 tuning 层验证（<code>AtLeast</code> 语义、<code>applyTuning</code> 恢复路径、二次写入失败备份）——确认 1 个 P2 bug</li><li><code>go vet</code> 通过，无新增编译问题</li><li>验证测试文件已删除，未污染仓库</li></ul></li></ul><h2 id="p0-阻断" tabindex="-1">P0 阻断 <a class="header-anchor" href="#p0-阻断" aria-label="Permalink to &quot;P0 阻断&quot;">​</a></h2><p>无。</p><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><p>无。</p><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="c-001-二次调优写入失败时丢失原始备份" tabindex="-1">C-001 二次调优写入失败时丢失原始备份 <a class="header-anchor" href="#c-001-二次调优写入失败时丢失原始备份" aria-label="Permalink to &quot;C-001 二次调优写入失败时丢失原始备份&quot;">​</a></h3><ul><li>文件：<code>go-gost/x/socket/tuning.go:240</code>（<code>applyTuning</code> 函数内循环）</li><li>现象：节点已调优过一次（备份文件中有原始值），第二次应用调优时若 <code>tuneWrite</code> 失败（内核不支持该参数，返回 EINVAL），代码执行 <code>delete(backup, k)</code>，导致原始备份永久丢失。此后执行 restore 无法恢复到最初值。</li><li>复现步骤： <ol><li>在临时 proc/sys 树中模拟 <code>net.ipv4.tcp_congestion_control=cubic</code></li><li>调用 <code>applyTuning([]string{&quot;bbr&quot;})</code> 成功，备份记录 <code>cubic</code></li><li>将 <code>tuneWrite</code> 替换为始终返回 <code>syscall.EINVAL</code> 的桩</li><li>再次调用 <code>applyTuning([]string{&quot;bbr&quot;})</code></li><li>检查 <code>loadTuneBackup()</code>：<code>net.ipv4.tcp_congestion_control</code> 的备份已消失（期望仍为 <code>cubic</code>）</li></ol></li><li>期望：写入失败时备份应保留（值未变，下次仍可恢复）。</li><li>实际：<code>delete(backup, k)</code> 删除了备份。</li><li>影响范围：仅二次调优且内核拒绝写入的边界场景。首次调优失败时删除备份是正确的（值确实没变）。</li><li>证据：自编写测试 <code>TestAuditC_TuneApplyFailKeepsBackup</code> 失败输出：<code>BUG 确认：二次写入失败后备份丢失，得到 &quot;&quot;，期望 cubic</code></li><li>修复方向：区分&quot;本次新增的备份&quot;和&quot;历史备份&quot;。只在 <code>!saved</code>（本次新备份）且写入失败时删除；历史备份（<code>saved==true</code>）写入失败时保留。或在 <code>want</code> 构建阶段记录哪些 key 是本次新增的。</li></ul><h2 id="p3-体验-健壮性" tabindex="-1">P3 体验/健壮性 <a class="header-anchor" href="#p3-体验-健壮性" aria-label="Permalink to &quot;P3 体验/健壮性&quot;">​</a></h2><h3 id="c-002-inboundprobeview-强制覆盖延迟探测的失败状态" tabindex="-1">C-002 <code>inboundProbeView</code> 强制覆盖延迟探测的失败状态 <a class="header-anchor" href="#c-002-inboundprobeview-强制覆盖延迟探测的失败状态" aria-label="Permalink to &quot;C-002 `inboundProbeView` 强制覆盖延迟探测的失败状态&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/node_latency.go:318</code></li><li>现象：<code>latencyProbe</code> 在所有测试点都失败时会设置 <code>OK=false, Error=&quot;测试点都连不上&quot;</code>，但 <code>inboundProbeView</code> 拿到结果后强制 <code>view.OK, view.Error = true, &quot;&quot;</code>，入站列表始终显示正常。</li><li>说明：设计意图可能是&quot;延迟点不通 ≠ 节点不可用&quot;，且每个点的详细错误保留在 <code>view.Points[].Error</code> 中，前端点开仍可见。因此定为 P3 而非 P2。但全失败时完全抹掉总体错误提示，运维无法从列表页察觉测试点配置问题（如测试点地址失效）。</li><li>修复方向：全失败时保留 <code>Error</code> 提示（如 <code>view.Error = node.Error</code>），或仅在部分成功时强制 OK。</li></ul><h3 id="c-003-applytuning-写入-sysctl-d-配置前未创建父目录" tabindex="-1">C-003 <code>applyTuning</code> 写入 sysctl.d 配置前未创建父目录 <a class="header-anchor" href="#c-003-applytuning-写入-sysctl-d-配置前未创建父目录" aria-label="Permalink to &quot;C-003 `applyTuning` 写入 sysctl.d 配置前未创建父目录&quot;">​</a></h3><ul><li>文件：<code>go-gost/x/socket/tuning.go:约262行</code></li><li>现象：<code>os.WriteFile(tuneConfPath, ...)</code> 前没有 <code>os.MkdirAll(filepath.Dir(tuneConfPath))</code>。代码只在写备份文件前创建了备份目录（<code>os.MkdirAll(filepath.Dir(tuneBackupPath), 0o755)</code>）。</li><li>影响：标准系统上 <code>/etc/sysctl.d/</code> 必然存在，实际触发概率极低。最小化容器/自定义路径场景下会返回&quot;写入失败&quot;错误。</li><li>修复方向：在写 conf 文件前加一行 <code>os.MkdirAll</code>。</li></ul><h3 id="c-004-调优配置文件注释中的品牌拼写错误" tabindex="-1">C-004 调优配置文件注释中的品牌拼写错误 <a class="header-anchor" href="#c-004-调优配置文件注释中的品牌拼写错误" aria-label="Permalink to &quot;C-004 调优配置文件注释中的品牌拼写错误&quot;">​</a></h3><ul><li>文件：<code>go-gost/x/socket/tuning.go:约260行</code></li><li>现象：<code>body := &quot;# Written by the FLYX panel (节点调优); remove via the panel to restore.\\n&quot;</code> 中的 &quot;FLYX&quot; 应为 &quot;FLVX&quot;。</li><li>影响：仅注释文案，不影响功能。</li></ul><h3 id="c-005-github-镜像缓存在-db-path-未设置时使用系统临时目录" tabindex="-1">C-005 GitHub 镜像缓存在 DB_PATH 未设置时使用系统临时目录 <a class="header-anchor" href="#c-005-github-镜像缓存在-db-path-未设置时使用系统临时目录" aria-label="Permalink to &quot;C-005 GitHub 镜像缓存在 DB_PATH 未设置时使用系统临时目录&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/gh_mirror.go:286-293</code>（<code>ghMirrorCacheDir</code>）</li><li>现象：<code>DB_PATH</code> 环境变量为空时，缓存目录为 <code>os.TempDir()/flvx-github-cache</code>。容器重启或系统清理 /tmp 后，缓存丢失，&quot;GitHub 不可达时返回旧副本&quot;的降级能力失效。</li><li>说明：生产部署通常设置 DB_PATH，实际影响有限。建议文档注明 DB_PATH 为必填，或在启动时校验。</li></ul><h2 id="验证通过的项-无问题" tabindex="-1">验证通过的项（无问题） <a class="header-anchor" href="#验证通过的项-无问题" aria-label="Permalink to &quot;验证通过的项（无问题）&quot;">​</a></h2><p>以下经实际运行测试确认逻辑正确：</p><ol><li><strong>C1 延迟配置解析</strong>（<code>parseLatencyTargets</code>）：空值/超10个/重名/超3个pinned/非法地址均正确报错；host 规范化正确。</li><li><strong>C1 节点自选回退</strong>（<code>targetsForNode</code>）：自选点全被删除时回退默认；损坏 JSON 回退默认。</li><li><strong>C1 改名跟随</strong>（<code>renamedTargets</code>/<code>syncNodeTargetChoices</code>）：同地址改名时节点选择跟随；地址变更时不跟随；删除的点被 drop。</li><li><strong>C1 离线跳过</strong>（<code>probeNodeLatency</code>）：<code>n.Status != 1</code> 时跳过；无测试点时跳过。</li><li><strong>C1 并发安全</strong>：<code>probeNodeLatency</code> 每个 goroutine 写独立 slice 槽位，无数据竞争；信号量+WaitGroup 无死锁。</li><li><strong>C3 线路分类</strong>（<code>classifyRoute</code>）：CN2/163/9929/4837/CMI/CMIN2 优先级正确；CN2+163 判为 CN2 GT；空 hops 判为&quot;未识别&quot;。</li><li><strong>C3 前缀匹配</strong>（<code>routeHopNet</code>）：9 个骨干前缀正确；<code>59.431.x.x</code> 不误匹配 <code>59.43.</code>。</li><li><strong>C3 缓存刷新</strong>（<code>routeFresh</code>）：24h 成功刷新、6h 失败重试、agent 升级立即重查、测试点改名/地址变更重查，均符合设计。</li><li><strong>C3 降级处理</strong>（<code>routePointFrom</code>）：旧 agent（&quot;未知命令&quot;）、无 NET_RAW 权限、DNS 失败均有明确中文错误。</li><li><strong>C4 SSRF 防护</strong>（<code>parseGHMirrorPath</code>）：非白名单仓库拒绝；<code>..</code> 路径穿越拒绝；非 github host 拒绝；api.github.com 的 query 非法时拒绝。</li><li><strong>C4 重定向限制</strong>（<code>ghMirrorCheckRedirect</code>）：仅允许 github.com 和 *.githubusercontent.com；<code>github.com.evil.com</code> 后缀欺骗被拒绝（<code>strings.HasSuffix</code> 精确匹配）。</li><li><strong>C4 300MB 限制</strong>：下载前检查 <code>ContentLength</code>，下载中使用 <code>io.LimitReader(..., 300MB+1)</code>，下载后校验，时机正确。</li><li><strong>C2 AtLeast 语义</strong>（<code>tuning.go satisfied</code>）：多值参数取最后一个数比较；已高于推荐值时跳过写入。</li><li><strong>C2 恢复路径</strong>（<code>applyTuning(nil)</code>）：原值写回、备份文件删除、conf 文件删除，均正确。</li><li><strong>C2 旧 agent 错误翻译</strong>（<code>node_tune.go</code>）：&quot;未知命令类型&quot;转为&quot;节点 agent 版本过旧&quot;，正确。</li></ol><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li><strong>真实节点调优</strong>：需 Linux root 节点实测 BBR 应用、<code>sysctl -a</code> 确认、<code>tuning-backup.json</code> 并发写。沙箱无节点权限，标为未验证。</li><li><strong>真实路由追踪</strong>：需节点 raw socket 权限实测 ICMP traceroute 和 Team Cymru DNS 查询。标为未验证。</li><li><strong>GitHub 镜像真实下载</strong>：沙箱 DNS 被拦截（*.github.com 解析到 198.18.x.x），无法实测下载/缓存/旧副本降级。标为未验证。</li><li><strong>延迟探测真实耗时</strong>：<code>probeNodeLatency</code> 的 16 并发、每点 4 次 ping 在百节点规模下的总耗时，需生产环境实测。代码层面无死锁，标为未验证。</li><li><strong>前端页面实际验证</strong>：无 live browser，未打开节点页/配置页确认延迟显示、调优弹窗、路由追踪 UI。需人工在浏览器确认。</li></ul>',24)])])}const p=e(d,[["render",r]]);export{h as __pageData,p as default};
